describe('No results found message', () => {
    beforeEach(() => {
        cy.intercept('GET', '/api/items', []).as('getEmptyItems');
        cy.visit('/items'); // Adjust the URL to your application
    });

    it('should display "No results found" message when API returns an empty list', () => {
        cy.wait('@getEmptyItems');
        cy.get('.no-results-message').should('be.visible').and('contain', 'No results found');
    });

    it('should not display any items when API returns an empty list', () => {
        cy.wait('@getEmptyItems');
        cy.get('.item').should('not.exist');
    });
});
